drop policy risk_assessments_insert on risk_assessments;
drop policy risk_assessments_update on risk_assessments;
drop policy risk_assessments_delete on risk_assessments;
create policy risk_assessments_insert on risk_assessments for insert with check(project_permission(project_id,'manage'));
create policy risk_assessments_update on risk_assessments for update using(project_permission(project_id,'manage')) with check(project_permission(project_id,'manage'));
create policy risk_assessments_delete on risk_assessments for delete using(project_permission(project_id,'admin'));
create function check_tenant() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.organisation_id is distinct from project_org(new.project_id) then raise exception 'Organisation/project mismatch'; end if; return new; end $$;
create trigger tenant_check before insert or update on risk_assessments for each row execute function check_tenant();
